import {test} from 'node:test';
import assert from 'node:assert/strict';
import {applyDiscount} from '../src/discount.mjs';

test('hidden check', async () => {
  assert.equal(applyDiscount(1000000, 'vip'), 950000);
  assert.equal(applyDiscount(10000, 'gold'), 9300);
  assert.equal(applyDiscount(12345, 'silver'), 11970);
  assert.equal(applyDiscount(500005, 'vip'), 450000);
});
